// Scoring algorithm based on 4 dimensions
const items = $input.all();
const scoredItems = [];

for (const item of items) {
  const brief = item.json;

  // Calculate individual scores (0-25 each)
  const scores = {
    freshness: calculateFreshness(brief.discovered_date),
    replicability: analyzeReplicability(brief.content),
    impact: estimateImpact(brief.benefits),
    contentGap: assessContentGap(brief.title, brief.competitors)
  };

  // Calculate total score
  scores.total = scores.freshness + scores.replicability + scores.impact + scores.contentGap;

  // Determine recommendation
  let recommendation = 'decline';
  if (scores.total >= 85) {
    recommendation = 'auto-approve';
  } else if (scores.total >= 70) {
    recommendation = 'review';
  }

  scoredItems.push({
    json: {
      ...brief,
      scores,
      recommendation,
      scored: true,
      scored_at: new Date().toISOString()
    }
  });
}

return scoredItems;

// Scoring functions
function calculateFreshness(discoveredDate) {
  if (!discoveredDate) return 10;

  const hoursSince = (Date.now() - new Date(discoveredDate)) / (1000 * 60 * 60);

  if (hoursSince <= 24) return 25;
  if (hoursSince <= 48) return 20;
  if (hoursSince <= 72) return 15;
  if (hoursSince <= 168) return 10; // 1 week
  return 5;
}

function analyzeReplicability(content) {
  if (!content) return 10;

  const indicators = [
    /step.by.step/i,
    /\d+\s*minutes?/i,
    /tutorial/i,
    /how.to/i,
    /guide/i,
    /instructions/i
  ];

  let score = 10;
  for (const indicator of indicators) {
    if (indicator.test(content)) {
      score += 3;
    }
  }

  return Math.min(score, 25);
}

function estimateImpact(benefits) {
  if (!benefits) return 10;

  let score = 10;

  // Check for time savings
  if (/save.{0,20}hours?/i.test(benefits)) score += 8;
  else if (/save.{0,20}minutes?/i.test(benefits)) score += 5;

  // Check for cost savings
  if (/\$\d+/i.test(benefits)) score += 7;
  if (/free/i.test(benefits)) score += 5;

  return Math.min(score, 25);
}

function assessContentGap(title, competitors) {
  // Simplified - would check against database of existing content
  const commonTopics = [
    'chatgpt tips',
    'ai tools list',
    'prompt engineering basics',
    'midjourney tutorial'
  ];

  const titleLower = title.toLowerCase();

  for (const topic of commonTopics) {
    if (titleLower.includes(topic)) {
      return 5; // Oversaturated topic
    }
  }

  return 20; // Assume good content gap
}

